begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
set local timezone='Pacific/Honolulu';
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at)
select ('a9000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','agenda-'||n||'@example.invalid','x',now(),now(),now() from generate_series(1,6) n;
insert into public.staff_users(user_id,role) values('a9000000-0000-4000-8000-000000000001','admin'),('a9000000-0000-4000-8000-000000000002','office'),('a9000000-0000-4000-8000-000000000003','technician'),('a9000000-0000-4000-8000-000000000004','technician');
insert into public.customers(id,name) values('c9000000-0000-4000-8000-000000000001','Klient Alfa'),('c9000000-0000-4000-8000-000000000002','Klient Beta');
insert into public.staff_customer_assignments(user_id,customer_id) values('a9000000-0000-4000-8000-000000000003','c9000000-0000-4000-8000-000000000001'),('a9000000-0000-4000-8000-000000000003','c9000000-0000-4000-8000-000000000002'),('a9000000-0000-4000-8000-000000000004','c9000000-0000-4000-8000-000000000001');
insert into public.customer_memberships(user_id,customer_id) values('a9000000-0000-4000-8000-000000000005','c9000000-0000-4000-8000-000000000001');
create function pg_temp.task(n integer,who integer default 3,delta integer default 0,state text default 'todo',client integer default 1) returns jsonb language sql as $$select public.save_crm_record(('c9000000-0000-4000-8000-'||lpad(client::text,12,'0'))::uuid,'tasks',('d9000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,null,jsonb_build_object('title',case when who=4 then 'HIDDEN OTHER TASK' else 'Działanie '||n end,'description','TASK DESCRIPTION','kind','follow_up','dueOn',to_char((now() at time zone 'Europe/Warsaw')::date+delta,'YYYY-MM-DD'),'assigneeId','a9000000-0000-4000-8000-'||lpad(who::text,12,'0'),'contactId',null,'state',state,'result',''))$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000002',true);
select pg_temp.task(1),pg_temp.task(2,3,-1),pg_temp.task(3,4,1),pg_temp.task(4,2,0,'todo',2),pg_temp.task(5,1,0,'done'),pg_temp.task(6,4,-1,'cancelled');
select is(public.team_crm_tasks()->>'total','4','Office sees all open tasks across customers and assignees');
select is(public.team_crm_tasks()->'counts'->>'today','2','Today count includes two assignees');
select is(public.team_crm_tasks()->'counts'->>'overdue','1','Overdue count only open');
select is(public.team_crm_tasks()->'counts'->>'upcoming','1','Upcoming count only open');
select is(public.team_crm_tasks()->'counts'->>'closed','2','Closed summary retained');
select is(public.team_crm_tasks()->>'viewerId','a9000000-0000-4000-8000-000000000002','Response bound to viewer');
select is(public.team_crm_tasks()->>'canManage','true','Explicit management capability');
select is(jsonb_array_length(public.team_crm_tasks()->'assignees'),4,'Options derived from task recipients');
select is(public.team_crm_tasks('all','all','a9000000-0000-4000-8000-000000000003')->>'total','2','Recipient filter works');
select is(public.team_crm_tasks('all','all','a9000000-0000-4000-8000-000000000003')->'counts'->>'open','2','Counters scoped to recipient');
select is(public.team_crm_tasks('today','todo')->>'total','2','Date and exact status combine');
select is(public.team_crm_tasks('overdue','cancelled')->>'total','1','Closed tasks can be filtered by historical deadline');
select is(public.team_crm_tasks('upcoming','open')->>'total','1','Upcoming open filter');
select is(public.team_crm_tasks('all','done')->>'total','1','Completed filter');
select is(public.team_crm_tasks('all','all')->>'total','6','All status filter');
select is(public.team_crm_tasks('all','open',null,'kLiEnT bEtA')->>'total','1','Literal case insensitive customer search');
select is(public.team_crm_tasks('all','open',null,'%')->>'total','0','Search percent is literal');
select is(public.team_crm_tasks('all','open',null,'TASK DESCRIPTION')->>'total','0','Descriptions not searched');
select is(public.team_crm_tasks('all','all','aaaaaaaa-0000-4000-8000-000000000000')->>'total','0','Unknown recipient reveals no data');
select throws_ok($$select public.team_crm_tasks('bad')$$,'22023',null,'Unknown date rejected');
select throws_ok($$select public.team_crm_tasks('all','bad')$$,'22023',null,'Unknown state rejected');
select throws_ok($$select public.team_crm_tasks('all','open',null,'',0)$$,'22023',null,'Zero page rejected');
select throws_ok($$select public.team_crm_tasks('all','open',null,'',100001)$$,'22023',null,'Oversized page rejected');
select throws_ok($$select public.team_crm_tasks('all','open',null,repeat('x',161))$$,'22023',null,'Long search rejected');
select throws_ok($$select public.team_crm_tasks('all','open',null,E'a\nb')$$,'22023',null,'Control search rejected');
select public.crm_task_progress('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001',0,'done','Office completed technician task');
select is(public.team_crm_tasks()->>'total','3','Office progress updates canonical task');
select is(public.team_crm_tasks()->'counts'->>'today','1','Completion updates counts');
select public.crm_task_progress('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001',1,'todo','Reopen');
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000001',true);
select is(public.team_crm_tasks()->>'total','4','Admin also sees whole available team');
select is(public.my_crm_tasks('open')->>'total','0','Personal agenda remains personal for admin');
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000003',true);
select throws_ok($$select public.team_crm_tasks()$$,'42501',null,'Assigned technician denied team and recipient options');
select is(public.my_crm_tasks('open')->>'total','2','Technician own agenda preserved');
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000005',true);
select throws_ok($$select public.team_crm_tasks()$$,'42501',null,'Portal client denied');
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000006',true);
select throws_ok($$select public.team_crm_tasks()$$,'42501',null,'No role denied');
reset role;
delete from public.staff_customer_assignments where user_id='a9000000-0000-4000-8000-000000000003';
set local role authenticated;
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000002',true);
select is(public.team_crm_tasks('all','all','a9000000-0000-4000-8000-000000000003')->'items'->0->>'assigneeAvailable','false','Revoked recipient remains visible for office with warning');
select is(public.team_crm_tasks('all','all','a9000000-0000-4000-8000-000000000003')->>'total','2','Unresolved work not hidden by revoked assignment');
select public.crm_task_progress('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000002',0,'done','Closed by office after revocation');
select is(public.team_crm_tasks()->'counts'->>'overdue','0','Office can close unavailable recipient task');
select throws_ok($$select public.crm_task_progress('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000002',1,'todo','')$$,'22023',null,'Quick progress cannot reopen unavailable recipient');
select pg_temp.task(n,2,-10,'done') from generate_series(20,43) n;
select is(jsonb_array_length(public.team_crm_tasks('all','all')->'items'),20,'Page bounded to twenty');
select is(jsonb_array_length(public.team_crm_tasks('all','all',null,'',2)->'items'),10,'Second page has remainder');
select ok(not exists(select 1 from jsonb_array_elements(public.team_crm_tasks('all','all')->'items') a join jsonb_array_elements(public.team_crm_tasks('all','all',null,'',2)->'items') b on a->>'id'=b->>'id'),'Stable pages do not overlap');
select is(public.team_crm_tasks('upcoming','open')->'items'->0->>'customerPage','2','Deep link counts all customer tasks');
select ok(public.team_crm_tasks()::text !~ 'old_data|new_data|PRIVATE NOTE|encrypted_password','No raw audit or notes projection');
reset role;
update public.customers set archived_at=now() where id='c9000000-0000-4000-8000-000000000002';
insert into public.account_access(user_id,blocked) values('a9000000-0000-4000-8000-000000000004',true);
set local role authenticated;
select is(public.team_crm_tasks()->>'total','2','Archived customer removed from list');
select is(public.team_crm_tasks('all','all','a9000000-0000-4000-8000-000000000004')->'items'->0->>'assigneeAvailable','false','Blocked recipient marked unavailable');
reset role;
insert into public.account_access(user_id,blocked) values('a9000000-0000-4000-8000-000000000002',true);
set local role authenticated;
select throws_ok($$select public.team_crm_tasks()$$,'42501',null,'Blocked office denied');
reset role;
set local role anon;
select throws_ok($$select public.team_crm_tasks()$$,'42501',null,'Anonymous execute denied');
select * from finish();
rollback;
